def match_union(grid, color):
 A=np.array(grid); pts=np.argwhere(A==color); pts=pts-pts.min(0); H,W=pts.max(0)+1; ms=[]; u=set()
 for r in range(A.shape[0]-H+1):
  for c in range(A.shape[1]-W+1):
   cells={(r+int(x),c+int(y)) for x,y in pts}
   if all(A[x,y]==0 for x,y in cells): ms.append((r,c)); u|=cells
 return ms,u
